package com.javaschoollab;

public class MatrixRotateDemo {

    // Rotates an n x n matrix 90 degrees clockwise, in place
    static void rotate(int[][] m) {
        int n = m.length;

        // Step 1: transpose (swap m[i][j] with m[j][i])
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int temp = m[i][j];
                m[i][j] = m[j][i];
                m[j][i] = temp;
            }
        }

        // Step 2: reverse each row
        for (int[] row : m) {
            for (int l = 0, r = row.length - 1; l < r; l++, r--) {
                int temp = row[l];
                row[l] = row[r];
                row[r] = temp;
            }
        }
    }

    public static void main(String[] args) {
        int[][] m = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        rotate(m);
        for (int[] row : m) {
            System.out.println(java.util.Arrays.toString(row));
        }
    }
}
// OUTPUT:
// [7, 4, 1]
// [8, 5, 2]
// [9, 6, 3]

package com.javaschoollab;

public class PrefixSumDemo {

    static int[] buildPrefix(int[] arr) {
        int[] pre = new int[arr.length];
        pre[0] = arr[0];
        for (int i = 1; i < arr.length; i++) {
            pre[i] = pre[i - 1] + arr[i];
        }
        return pre;
    }

    // Sum of arr[l..r] inclusive, in O(1) using the prefix array
    static int rangeSum(int[] pre, int l, int r) {
        if (l == 0) return pre[r];
        return pre[r] - pre[l - 1];
    }

    public static void main(String[] args) {
        int[] arr = {2, 4, 6, 8, 10};
        int[] pre = buildPrefix(arr);

        System.out.println("Sum(1, 3) = " + rangeSum(pre, 1, 3)); // 4+6+8
        System.out.println("Sum(0, 4) = " + rangeSum(pre, 0, 4)); // whole array
    }
}
// OUTPUT:
// Sum(1, 3) = 18
// Sum(0, 4) = 30

package com.javaschoollab;

import java.util.HashMap;
import java.util.Map;

public class SubarraySumEqualsKDemo {

    // Counts subarrays whose sum equals k, in O(n)
    static int countSubarraysWithSum(int[] arr, int k) {
        Map<Integer, Integer> prefixCount = new HashMap<>();
        prefixCount.put(0, 1);   // empty prefix, needed for subarrays starting at index 0

        int runningSum = 0;
        int count = 0;

        for (int num : arr) {
            runningSum += num;

            // If (runningSum - k) was seen before, those prefixes mark subarrays summing to k
            count += prefixCount.getOrDefault(runningSum - k, 0);

            prefixCount.merge(runningSum, 1, Integer::sum);
        }
        return count;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, -2, 5};
        System.out.println(countSubarraysWithSum(arr, 5));
    }
}
// OUTPUT:
// 3
// (subarrays: [2,3], [3,-2,5]... - three subarrays sum to 5)

package com.javaschoollab;

public class SuffixSumDemo {

    static int[] buildSuffix(int[] arr) {
        int n = arr.length;
        int[] suf = new int[n];
        suf[n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suf[i] = suf[i + 1] + arr[i];
        }
        return suf;
    }

    public static void main(String[] args) {
        int[] arr = {2, 4, 6, 8, 10};
        int[] suf = buildSuffix(arr);

        System.out.println("Total from index 2 to end: " + suf[2]); // 6+8+10
        System.out.println("Total from index 0 to end: " + suf[0]); // whole array
    }
}
// OUTPUT:
// Total from index 2 to end: 24
// Total from index 0 to end: 30

package com.javaschoollab;

public class ProductExceptSelfDemo {

    static int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];

        // Pass 1: result[i] = product of everything to the LEFT of i
        result[0] = 1;
        for (int i = 1; i < n; i++) {
            result[i] = result[i - 1] * nums[i - 1];
        }

        // Pass 2: multiply in everything to the RIGHT of i, using a running suffix product
        int rightProduct = 1;
        for (int i = n - 1; i >= 0; i--) {
            result[i] *= rightProduct;
            rightProduct *= nums[i];
        }
        return result;
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 4};
        System.out.println(java.util.Arrays.toString(productExceptSelf(nums)));
    }
}
// OUTPUT:
// [24, 12, 8, 6]
// (index 0: 2*3*4=24, index 1: 1*3*4=12, index 2: 1*2*4=8, index 3: 1*2*3=6)

package com.javaschoollab;

public class DifferenceArrayDemo {

    public static void main(String[] args) {
        int n = 6;
        int[] diff = new int[n + 1];   // one extra slot to safely do r+1

        // Apply "add 3 to range [1, 3]"
        applyRangeUpdate(diff, 1, 3, 3);
        // Apply "add 2 to range [2, 5]"
        applyRangeUpdate(diff, 2, 5, 2);

        int[] result = new int[n];
        result[0] = diff[0];
        for (int i = 1; i < n; i++) {
            result[i] = result[i - 1] + diff[i]; // reconstruct via prefix sum
        }

        System.out.println(java.util.Arrays.toString(result));
    }

    static void applyRangeUpdate(int[] diff, int l, int r, int val) {
        diff[l] += val;
        diff[r + 1] -= val;
    }
}
// OUTPUT:
// [0, 3, 5, 5, 2, 2]
// index0=0, index1=3, index2=3+2=5, index3=5, index4=2, index5=2

package com.javaschoollab;

// A common real interview problem: "Corporate Flight Bookings"
// bookings[i] = {first, last, seats} means add 'seats' seats to every
// flight number from first to last (1-indexed), for all bookings.
// Return the total seats booked on each flight.

public class FlightBookingsDemo {

    static int[] corpFlightBookings(int[][] bookings, int n) {
        int[] diff = new int[n + 1];   // 1-indexed flights, so size n+1

        for (int[] b : bookings) {
            int first = b[0], last = b[1], seats = b[2];
            diff[first - 1] += seats;         // convert to 0-indexed
            if (last < n) diff[last] -= seats;
        }

        int[] answer = new int[n];
        answer[0] = diff[0];
        for (int i = 1; i < n; i++) {
            answer[i] = answer[i - 1] + diff[i];
        }
        return answer;
    }

    public static void main(String[] args) {
        int[][] bookings = {{1, 2, 10}, {2, 3, 20}, {2, 5, 25}};
        System.out.println(java.util.Arrays.toString(corpFlightBookings(bookings, 5)));
    }
}
// OUTPUT:
// [10, 55, 45, 25, 25]

package com.javaschoollab;

public class KadaneDemo {

    static int maxSubarraySum(int[] arr) {
        int currentSum = arr[0];
        int maxSum = arr[0];

        for (int i = 1; i < arr.length; i++) {
            currentSum = Math.max(arr[i], currentSum + arr[i]);
            maxSum = Math.max(maxSum, currentSum);
        }
        return maxSum;
    }

    public static void main(String[] args) {
        int[] arr = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
        System.out.println(maxSubarraySum(arr));
    }
}
// OUTPUT:
// 6
// (subarray [4, -1, 2, 1] sums to 6)

package com.javaschoollab;

public class KadaneWithIndicesDemo {

    static int[] maxSubarrayWithBounds(int[] arr) {
        int currentSum = arr[0];
        int maxSum = arr[0];
        int start = 0, end = 0, tempStart = 0;

        for (int i = 1; i < arr.length; i++) {
            if (arr[i] > currentSum + arr[i]) {
                currentSum = arr[i];
                tempStart = i;              // restarting here
            } else {
                currentSum += arr[i];       // extending the previous run
            }

            if (currentSum > maxSum) {
                maxSum = currentSum;
                start = tempStart;
                end = i;
            }
        }
        return new int[]{maxSum, start, end};
    }

    public static void main(String[] args) {
        int[] allNegative = {-8, -3, -6, -2, -5, -4};
        int[] result = maxSubarrayWithBounds(allNegative);
        System.out.println("Max sum: " + result[0] + ", from index " + result[1] + " to " + result[2]);
    }
}
// OUTPUT:
// Max sum: -2, from index 3 to 3
// (the single least-negative element, -2, wins when everything is negative)

package com.javaschoollab;

public class FixedWindowDemo {

    // Maximum sum of any k consecutive elements
    static int maxSumOfSizeK(int[] arr, int k) {
        int windowSum = 0;
        for (int i = 0; i < k; i++) {
            windowSum += arr[i];      // build the first window
        }

        int maxSum = windowSum;
        for (int right = k; right < arr.length; right++) {
            windowSum += arr[right] - arr[right - k];  // slide: add new, drop old
            maxSum = Math.max(maxSum, windowSum);
        }
        return maxSum;
    }

    public static void main(String[] args) {
        int[] arr = {2, 1, 5, 1, 3, 2};
        System.out.println(maxSumOfSizeK(arr, 3));
    }
}
// OUTPUT:
// 9
// (window [5, 1, 3] sums to 9)

package com.javaschoollab;

public class VariableWindowDemo {

    // Length of the smallest contiguous subarray whose sum is >= target, or 0 if none exists
    static int minSubArrayLen(int target, int[] arr) {
        int left = 0;
        int windowSum = 0;
        int minLen = Integer.MAX_VALUE;

        for (int right = 0; right < arr.length; right++) {
            windowSum += arr[right];   // grow the window

            // shrink from the left while the condition still holds
            while (windowSum >= target) {
                minLen = Math.min(minLen, right - left + 1);
                windowSum -= arr[left];
                left++;
            }
        }
        return minLen == Integer.MAX_VALUE ? 0 : minLen;
    }

    public static void main(String[] args) {
        int[] arr = {2, 3, 1, 2, 4, 3};
        System.out.println(minSubArrayLen(7, arr));
    }
}
// OUTPUT:
// 2
// (subarray [4, 3] sums to 7 in only 2 elements)

package com.javaschoollab;

public class TwoSumSortedDemo {

    // Array is SORTED. Find two numbers that add up to target.
    static int[] twoSumSorted(int[] arr, int target) {
        int left = 0, right = arr.length - 1;

        while (left < right) {
            int sum = arr[left] + arr[right];
            if (sum == target) {
                return new int[]{left, right};
            } else if (sum < target) {
                left++;          // sum too small, need a bigger value -> move left up
            } else {
                right--;         // sum too big, need a smaller value -> move right down
            }
        }
        return new int[]{-1, -1};
    }

    public static void main(String[] args) {
        int[] arr = {1, 3, 5, 7, 9, 11};
        System.out.println(java.util.Arrays.toString(twoSumSorted(arr, 12)));
    }
}
// OUTPUT:
// [1, 4]
// (arr[1]=3 + arr[4]=9 = 12)

package com.javaschoollab;

public class RemoveDuplicatesDemo {

    // arr must be sorted. Returns the new length; the first 'newLength'
    // slots of arr hold the unique elements in order.
    static int removeDuplicates(int[] arr) {
        if (arr.length == 0) return 0;

        int writeIndex = 1;   // arr[0] is always kept
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != arr[writeIndex - 1]) {
                arr[writeIndex] = arr[i];
                writeIndex++;
            }
        }
        return writeIndex;
    }

    public static void main(String[] args) {
        int[] arr = {1, 1, 2, 2, 2, 3, 4, 4, 5};
        int newLength = removeDuplicates(arr);

        System.out.println("New length: " + newLength);
        System.out.println("Unique part: " +
            java.util.Arrays.toString(java.util.Arrays.copyOf(arr, newLength)));
    }
}
// OUTPUT:
// New length: 5
// Unique part: [1, 2, 3, 4, 5]

package com.javaschoollab;

public class FindDuplicateArrayDemo {

    // Array of n+1 integers, each in [1, n]. Exactly one value repeats
    // (possibly more than once). Find it in O(n) time, O(1) space, without
    // modifying the array - by treating values as "next index" pointers,
    // which forces a cycle to exist (Floyd's algorithm on an implicit list).
    static int findDuplicate(int[] nums) {
        int slow = nums[0];
        int fast = nums[0];

        // Phase 1: find the meeting point inside the cycle
        do {
            slow = nums[slow];
            fast = nums[nums[fast]];
        } while (slow != fast);

        // Phase 2: find the cycle's entrance == the duplicate value
        slow = nums[0];
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[fast];
        }
        return slow;
    }

    public static void main(String[] args) {
        int[] nums = {1, 3, 4, 2, 2};
        System.out.println(findDuplicate(nums));
    }
}
// OUTPUT:
// 2

package com.javaschoollab;

// Middle of an array/list, in one pass, using fast=2x, slow=1x
public class MiddleOfSequenceDemo {

    static int findMiddleIndex(int[] arr) {
        int slow = 0, fast = 0;
        while (fast < arr.length - 1 && fast + 1 < arr.length) {
            slow++;
            fast += 2;
        }
        return slow;   // when fast reaches the end, slow sits at the middle
    }

    public static void main(String[] args) {
        int[] arr = {10, 20, 30, 40, 50, 60, 70};
        int mid = findMiddleIndex(arr);
        System.out.println("Middle index: " + mid + ", value: " + arr[mid]);
    }
}
// OUTPUT:
// Middle index: 3, value: 40

package com.javaschoollab;

public class RotateWithExtraSpaceDemo {

    // O(n) time, O(n) space
    static void rotateRight(int[] arr, int k) {
        int n = arr.length;
        k = k % n;   // rotating by n is a no-op
        int[] rotated = new int[n];

        for (int i = 0; i < n; i++) {
            rotated[(i + k) % n] = arr[i];
        }
        System.arraycopy(rotated, 0, arr, 0, n);
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6, 7};
        rotateRight(arr, 3);
        System.out.println(java.util.Arrays.toString(arr));
    }
}
// OUTPUT:
// [5, 6, 7, 1, 2, 3, 4]

package com.javaschoollab;

public class RotateInPlaceDemo {

    static void rotateRight(int[] arr, int k) {
        int n = arr.length;
        k = k % n;

        reverse(arr, 0, n - 1);       // reverse everything
        reverse(arr, 0, k - 1);       // reverse the first k (now correctly placed values)
        reverse(arr, k, n - 1);       // reverse the rest
    }

    static void reverse(int[] arr, int left, int right) {
        while (left < right) {
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6, 7};
        rotateRight(arr, 3);
        System.out.println(java.util.Arrays.toString(arr));
    }
}
// OUTPUT:
// [5, 6, 7, 1, 2, 3, 4]

package com.javaschoollab;

public class CyclicSortDemo {

    // Sorts an array containing exactly the numbers 1..n, in O(n)
    static void cyclicSort(int[] arr) {
        int i = 0;
        while (i < arr.length) {
            int correctIndex = arr[i] - 1;   // where arr[i] SHOULD live
            if (arr[i] != arr[correctIndex]) {
                // swap arr[i] into its correct slot
                int temp = arr[i];
                arr[i] = arr[correctIndex];
                arr[correctIndex] = temp;
            } else {
                i++;   // arr[i] is already correct (or a duplicate), move on
            }
        }
    }

    public static void main(String[] args) {
        int[] arr = {3, 1, 5, 4, 2};
        cyclicSort(arr);
        System.out.println(java.util.Arrays.toString(arr));
    }
}
// OUTPUT:
// [1, 2, 3, 4, 5]

package com.javaschoollab;

import java.util.ArrayList;
import java.util.List;

public class FindAllMissingNumbersDemo {

    // arr has n elements, values in [1, n], some missing, some duplicated.
    // Find every missing number in O(n) time, O(1) extra space (besides output).
    static List<Integer> findMissingNumbers(int[] arr) {
        int i = 0;
        while (i < arr.length) {
            int correctIndex = arr[i] - 1;
            if (arr[i] != arr[correctIndex]) {
                int temp = arr[i];
                arr[i] = arr[correctIndex];
                arr[correctIndex] = temp;
            } else {
                i++;
            }
        }

        List<Integer> missing = new ArrayList<>();
        for (int idx = 0; idx < arr.length; idx++) {
            if (arr[idx] != idx + 1) {
                missing.add(idx + 1);   // the value that SHOULD be here
            }
        }
        return missing;
    }

    public static void main(String[] args) {
        int[] arr = {4, 3, 3, 7, 1, 6, 1};   // n=7, missing 2 and 5
        System.out.println(findMissingNumbers(arr));
    }
}
// OUTPUT:
// [2, 5]

package com.javaschoollab;

public class DutchFlagDemo {

    // Sorts an array of only 0s, 1s and 2s in one pass, O(n) time, O(1) space
    static void sortColors(int[] arr) {
        int low = 0, mid = 0, high = arr.length - 1;

        while (mid <= high) {
            if (arr[mid] == 0) {
                swap(arr, low, mid);
                low++;
                mid++;              // the swapped-in value at mid is known-good (0 or 1), safe to advance
            } else if (arr[mid] == 1) {
                mid++;               // 1 already belongs in the middle zone
            } else {                 // arr[mid] == 2
                swap(arr, mid, high);
                high--;              // do NOT advance mid - the swapped-in value is unexamined
            }
        }
    }

    static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        int[] arr = {2, 0, 2, 1, 1, 0};
        sortColors(arr);
        System.out.println(java.util.Arrays.toString(arr));
    }
}
// OUTPUT:
// [0, 0, 1, 1, 2, 2]

package com.javaschoollab;

// 3-way partition used inside Quicksort for arrays with many duplicate pivots
public class ThreeWayPartitionDemo {

    static void quickSort3Way(int[] arr, int lo, int hi) {
        if (lo >= hi) return;

        int pivot = arr[lo];
        int lt = lo, gt = hi, i = lo + 1;

        // Exactly the Dutch flag pattern: partition into <pivot, ==pivot, >pivot
        while (i <= gt) {
            if (arr[i] < pivot) {
                swap(arr, lt++, i++);
            } else if (arr[i] > pivot) {
                swap(arr, i, gt--);
            } else {
                i++;
            }
        }
        // arr[lo..lt-1] < pivot, arr[lt..gt] == pivot, arr[gt+1..hi] > pivot
        quickSort3Way(arr, lo, lt - 1);
        quickSort3Way(arr, gt + 1, hi);
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }

    public static void main(String[] args) {
        int[] arr = {5, 3, 5, 5, 1, 5, 9, 5};
        quickSort3Way(arr, 0, arr.length - 1);
        System.out.println(java.util.Arrays.toString(arr));
    }
}
