package com.javaschoollab;

public class ManacherDemo {

    static String longestPalindrome(String s) {
        String t = transform(s);
        int n = t.length();
        int[] p = new int[n];   // p[i] = radius of palindrome centered at i in t
        int center = 0, right = 0;

        for (int i = 1; i < n - 1; i++) {
            int mirror = 2 * center - i;
            if (i < right) {
                p[i] = Math.min(right - i, p[mirror]);   // reuse mirrored work
            }
            while (t.charAt(i + p[i] + 1) == t.charAt(i - p[i] - 1)) {
                p[i]++;
            }
            if (i + p[i] > right) {
                center = i;
                right = i + p[i];
            }
        }

        int maxLen = 0, centerIndex = 0;
        for (int i = 1; i < n - 1; i++) {
            if (p[i] > maxLen) {
                maxLen = p[i];
                centerIndex = i;
            }
        }
        int start = (centerIndex - maxLen) / 2;   // map back to the original string
        return s.substring(start, start + maxLen);
    }

    static String transform(String s) {
        StringBuilder sb = new StringBuilder("^");
        for (char c : s.toCharArray()) sb.append('#').append(c);
        sb.append("#$");
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(longestPalindrome("babad"));
        System.out.println(longestPalindrome("forgeeksskeegfor"));
    }
}
// OUTPUT:
// bab
// geeksskeeg

package com.javaschoollab;

import java.util.HashMap;
import java.util.Map;

public class TrieDemo {

    static class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        boolean isEndOfWord = false;
    }

    static class Trie {
        private final TrieNode root = new TrieNode();

        void insert(String word) {
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            }
            node.isEndOfWord = true;
        }

        boolean search(String word) {
            TrieNode node = traverse(word);
            return node != null && node.isEndOfWord;
        }

        boolean startsWith(String prefix) {
            return traverse(prefix) != null;
        }

        private TrieNode traverse(String s) {
            TrieNode node = root;
            for (char c : s.toCharArray()) {
                node = node.children.get(c);
                if (node == null) return null;
            }
            return node;
        }
    }

    public static void main(String[] args) {
        Trie trie = new Trie();
        trie.insert("apple");

        System.out.println(trie.search("apple"));      // exact word inserted
        System.out.println(trie.search("app"));         // not inserted as a full word
        System.out.println(trie.startsWith("app"));      // but "app" IS a prefix
    }
}
// OUTPUT:
// true
// false
// true

package com.javaschoollab;

import java.util.*;

public class WordSearchTrieDemo {

    static class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        String word = null;   // set at the node where a full word ends
    }

    static TrieNode buildTrie(String[] words) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode node = root;
            for (char c : w.toCharArray()) {
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            }
            node.word = w;
        }
        return root;
    }

    static void dfs(char[][] board, int r, int c, TrieNode node, Set<String> found) {
        char ch = board[r][c];
        TrieNode next = node.children.get(ch);
        if (next == null) return;   // prune: no dictionary word continues with this letter

        if (next.word != null) {
            found.add(next.word);
        }

        board[r][c] = '#';   // mark visited
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length && board[nr][nc] != '#') {
                dfs(board, nr, nc, next, found);
            }
        }
        board[r][c] = ch;   // backtrack: restore for other search paths
    }

    static List<String> findWords(char[][] board, String[] words) {
        TrieNode root = buildTrie(words);
        Set<String> found = new HashSet<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                dfs(board, r, c, root, found);
            }
        }
        return new ArrayList<>(found);
    }

    public static void main(String[] args) {
        char[][] board = {
            {'o','a','a','n'},
            {'e','t','a','e'},
            {'i','h','k','r'},
            {'i','f','l','v'}
        };
        System.out.println(findWords(board, new String[]{"oath", "pea", "eat", "rain"}));
    }
}
// OUTPUT:
// [eat, oath]

