// true
// false

package com.javaschoollab;

public class CycleLengthDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    // Once a meeting point is found, walk the cycle again to measure its length
    static int cycleLength(Node head) {
        Node slow = head, fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                int length = 1;
                Node cur = slow.next;
                while (cur != slow) {
                    length++;
                    cur = cur.next;
                }
                return length;
            }
        }
        return 0;   // no cycle
    }

    public static void main(String[] args) {
        Node a = new Node(1);
        Node b = new Node(2);
        Node c = new Node(3);
        Node d = new Node(4);
        a.next = b; b.next = c; c.next = d; d.next = b;   // cycle of length 3: b -> c -> d -> b

        System.out.println("Cycle length: " + cycleLength(a));
    }
}
