        int a = 2, c = 3;

        // Phase 1 meets somewhere inside the cycle after slow travels a + b steps,
        // where b is some value determined by when fast laps slow.
        // Phase 2 proves: distance(head -> start) == distance(meetingPoint -> start)
        System.out.println("a (head to start)        : " + a);
        System.out.println("This equals the remaining distance from the meeting point to the start,");
        System.out.println("which is exactly what advancing both pointers by 1 step converges on.");
    }
}
// OUTPUT:
// a (head to start)        : 2
// This equals the remaining distance from the meeting point to the start,
// which is exactly what advancing both pointers by 1 step converges on.

package com.javaschoollab;

public class MergeTwoSortedListsDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    static Node mergeTwoLists(Node l1, Node l2) {
        Node dummy = new Node(-1);   // placeholder simplifies edge cases at the head
        Node tail = dummy;

        while (l1 != null && l2 != null) {
            if (l1.val <= l2.val) {
                tail.next = l1;
                l1 = l1.next;
            } else {
                tail.next = l2;
                l2 = l2.next;
            }
            tail = tail.next;
        }
        tail.next = (l1 != null) ? l1 : l2;   // attach whichever list has leftovers

        return dummy.next;
    }

    static void print(Node head) {
        StringBuilder sb = new StringBuilder();
        while (head != null) {
            sb.append(head.val).append(" -> ");
            head = head.next;
        }
        System.out.println(sb + "null");
    }

    public static void main(String[] args) {
        Node l1 = new Node(1);
        l1.next = new Node(3);
        l1.next.next = new Node(5);

        Node l2 = new Node(2);
        l2.next = new Node(4);
        l2.next.next = new Node(6);

        print(mergeTwoLists(l1, l2));
    }
}
// OUTPUT:
// 1 -> 2 -> 3 -> 4 -> 5 -> 6 -> null

package com.javaschoollab;

import java.util.PriorityQueue;

public class MergeKSortedListsDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    static Node mergeKLists(Node[] lists) {
        PriorityQueue<Node> heap = new PriorityQueue<>((a, b) -> a.val - b.val);
        for (Node head : lists) {
            if (head != null) heap.offer(head);
        }

        Node dummy = new Node(-1);
        Node tail = dummy;

        while (!heap.isEmpty()) {
            Node smallest = heap.poll();
            tail.next = smallest;
            tail = tail.next;

            if (smallest.next != null) {
                heap.offer(smallest.next);   // push the next node from the same list
            }
        }
        return dummy.next;
    }

    static void print(Node head) {
        StringBuilder sb = new StringBuilder();
        while (head != null) {
            sb.append(head.val).append(" -> ");
            head = head.next;
        }
        System.out.println(sb + "null");
    }

    public static void main(String[] args) {
        Node l1 = new Node(1); l1.next = new Node(4); l1.next.next = new Node(5);
        Node l2 = new Node(1); l2.next = new Node(3); l2.next.next = new Node(4);
        Node l3 = new Node(2); l3.next = new Node(6);

        print(mergeKLists(new Node[]{l1, l2, l3}));
    }
}
// OUTPUT:
// 1 -> 1 -> 2 -> 3 -> 4 -> 4 -> 5 -> 6 -> null

package com.javaschoollab;

import java.util.HashSet;
import java.util.Set;

public class IntersectionHashSetDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    // O(n + m) time, O(n) space
    static Node getIntersectionNode(Node headA, Node headB) {
        Set<Node> visited = new HashSet<>();
        Node cur = headA;
        while (cur != null) {
            visited.add(cur);
            cur = cur.next;
        }

        cur = headB;
        while (cur != null) {
            if (visited.contains(cur)) {
                return cur;   // first shared node found
            }
            cur = cur.next;
        }
        return null;
    }

    public static void main(String[] args) {
        Node shared = new Node(8);
        shared.next = new Node(9);

        Node a = new Node(1);
        a.next = new Node(2);
        a.next.next = shared;

        Node b = new Node(3);
        b.next = shared;

        Node result = getIntersectionNode(a, b);
        System.out.println(result != null ? result.val : "no intersection");
    }
}
// OUTPUT:
// 8

package com.javaschoollab;

public class IntersectionTwoPointerDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    // O(n + m) time, O(1) space - no HashSet needed
    static Node getIntersectionNode(Node headA, Node headB) {
        if (headA == null || headB == null) return null;

        Node pA = headA, pB = headB;

        // When pA falls off list A, redirect it to headB (and vice versa) -
        // this equalizes the distance each pointer travels before meeting.
        while (pA != pB) {
            pA = (pA == null) ? headB : pA.next;
            pB = (pB == null) ? headA : pB.next;
        }
        return pA;   // either the intersection node, or null (both fell off together)
    }

    public static void main(String[] args) {
        Node shared = new Node(8);
        shared.next = new Node(9);

        Node a = new Node(1);
        a.next = new Node(2);
        a.next.next = shared;

        Node b = new Node(3);
        b.next = shared;

        Node result = getIntersectionNode(a, b);
        System.out.println(result != null ? result.val : "no intersection");
    }
}
// OUTPUT:
// 8

package com.javaschoollab;

public class RemoveNthFromEndDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    static Node removeNthFromEnd(Node head, int n) {
        Node dummy = new Node(-1);
        dummy.next = head;

        Node fast = dummy, slow = dummy;

        // Move fast n+1 steps ahead, creating a gap of n between fast and slow
        for (int i = 0; i <= n; i++) {
            fast = fast.next;
        }

        // Move both until fast reaches the end - slow now sits just BEFORE the target
        while (fast != null) {
            fast = fast.next;
            slow = slow.next;
        }

        slow.next = slow.next.next;   // skip over the node to remove
        return dummy.next;
    }

    static void print(Node head) {
        StringBuilder sb = new StringBuilder();
        while (head != null) {
            sb.append(head.val).append(" -> ");
            head = head.next;
        }
        System.out.println(sb + "null");
    }

    public static void main(String[] args) {
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);
        head.next.next.next.next = new Node(5);

        print(removeNthFromEnd(head, 2));   // remove the 2nd node from the end
    }
}
// OUTPUT:
// 1 -> 2 -> 3 -> 5 -> null

