package com.javaschoollab;

public class PalindromeLinkedListDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    static boolean isPalindrome(Node head) {
        if (head == null || head.next == null) return true;

        // Step 1: find the middle using fast/slow
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // Step 2: reverse the second half, starting from slow
        Node secondHalf = reverse(slow);

        // Step 3: compare the first half against the reversed second half
        Node p1 = head, p2 = secondHalf;
        boolean result = true;
        while (p2 != null) {
            if (p1.val != p2.val) {
                result = false;
                break;
            }
            p1 = p1.next;
            p2 = p2.next;
        }
        return result;
    }

    static Node reverse(Node head) {
        Node prev = null;
        while (head != null) {
            Node next = head.next;
            head.next = prev;
            prev = head;
            head = next;
        }
        return prev;
    }

    public static void main(String[] args) {
        Node a = new Node(1);
        a.next = new Node(2);
        a.next.next = new Node(2);
        a.next.next.next = new Node(1);

        System.out.println(isPalindrome(a));
    }
}
// OUTPUT:
// true

package com.javaschoollab;

// The simplest CORRECT (if not the fastest) LRU Cache: LinkedHashMap already
// tracks access order internally and supports O(1) eviction via removeEldestEntry.
import java.util.LinkedHashMap;
import java.util.Map;

public class SimpleLruCacheDemo {

    static class LRUCache<K, V> extends LinkedHashMap<K, V> {
        private final int capacity;

        LRUCache(int capacity) {
            super(capacity, 0.75f, true);   // 'true' = order by ACCESS, not insertion
            this.capacity = capacity;
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > capacity;   // auto-evict once over capacity
        }
    }

    public static void main(String[] args) {
        LRUCache<Integer, String> cache = new LRUCache<>(2);
        cache.put(1, "A");
        cache.put(2, "B");
        cache.get(1);            // touches 1 -> now most recently used
        cache.put(3, "C");       // evicts 2 (least recently used)

        System.out.println(cache.containsKey(1));
        System.out.println(cache.containsKey(2));   // evicted
        System.out.println(cache.containsKey(3));
    }
}
// OUTPUT:
// true
// false
// true

package com.javaschoollab;

import java.util.HashMap;
import java.util.Map;

public class LRUCacheFromScratchDemo {

    static class Node {
        int key, value;
        Node prev, next;
        Node(int key, int value) { this.key = key; this.value = value; }
    }

    static class LRUCache {
        private final int capacity;
        private final Map<Integer, Node> map = new HashMap<>();
        private final Node head = new Node(-1, -1);   // dummy head (MRU side)
        private final Node tail = new Node(-1, -1);   // dummy tail (LRU side)

        LRUCache(int capacity) {
            this.capacity = capacity;
            head.next = tail;
            tail.prev = head;
        }

        int get(int key) {
            if (!map.containsKey(key)) return -1;
            Node node = map.get(key);
            moveToFront(node);
            return node.value;
        }

        void put(int key, int value) {
            if (map.containsKey(key)) {
                Node node = map.get(key);
                node.value = value;
                moveToFront(node);
                return;
            }
            if (map.size() == capacity) {
                Node lru = tail.prev;
                remove(lru);
                map.remove(lru.key);
            }
            Node newNode = new Node(key, value);
            map.put(key, newNode);
            addToFront(newNode);
        }

        private void remove(Node node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }

        private void addToFront(Node node) {
            node.next = head.next;
            node.prev = head;
            head.next.prev = node;
            head.next = node;
        }

        private void moveToFront(Node node) {
            remove(node);
            addToFront(node);
        }
    }

    public static void main(String[] args) {
        LRUCache cache = new LRUCache(2);
        cache.put(1, 10);
        cache.put(2, 20);
        System.out.println(cache.get(1));   // touches 1 -> most recently used
        cache.put(3, 30);                    // evicts 2 (least recently used)
        System.out.println(cache.get(2));    // -1, evicted
        System.out.println(cache.get(3));
    }
}
// OUTPUT:
// 10
// -1
// 30

