public class LinkedListStackDemo {

    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    static class Stack {
        private Node top;

        void push(int val) {
            Node newNode = new Node(val);
            newNode.next = top;
            top = newNode;
        }

        int pop() {
            if (top == null) throw new RuntimeException("Stack is empty");
            int val = top.val;
            top = top.next;
            return val;
        }

        int peek() {
            if (top == null) throw new RuntimeException("Stack is empty");
            return top.val;
        }

        boolean isEmpty() {
            return top == null;
        }
    }

