package com.javaschoollab;

public class LargestRectangleBruteForceDemo {

    // O(n^2) - for each bar, expand left and right while bars are tall enough
    static int largestRectangleArea(int[] heights) {
        int maxArea = 0;
        for (int i = 0; i < heights.length; i++) {
            int minHeight = heights[i];
            for (int j = i; j < heights.length; j++) {
                minHeight = Math.min(minHeight, heights[j]);
                maxArea = Math.max(maxArea, minHeight * (j - i + 1));
            }
        }
        return maxArea;
    }

    public static void main(String[] args) {
        int[] heights = {2, 1, 5, 6, 2, 3};
        System.out.println(largestRectangleArea(heights));
    }
}
// OUTPUT:
// 10

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class LargestRectangleStackDemo {

    static int largestRectangleArea(int[] heights) {
        Deque<Integer> stack = new ArrayDeque<>();   // increasing stack of indices
        int maxArea = 0;
        int n = heights.length;

        for (int i = 0; i <= n; i++) {
            // Use height 0 as a sentinel at the end to flush any remaining bars
            int currentHeight = (i == n) ? 0 : heights[i];

            while (!stack.isEmpty() && heights[stack.peek()] >= currentHeight) {
                int height = heights[stack.pop()];
                // width spans from the new stack top (exclusive) to i (exclusive)
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, height * width);
            }
            stack.push(i);
        }
        return maxArea;
    }

    public static void main(String[] args) {
        int[] heights = {2, 1, 5, 6, 2, 3};
        System.out.println(largestRectangleArea(heights));
    }
}
// OUTPUT:
// 10

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class StockSpanDemo {

    static int[] calculateSpan(int[] prices) {
        int n = prices.length;
        int[] span = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();   // holds indices, decreasing price

        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && prices[stack.peek()] <= prices[i]) {
                stack.pop();   // this earlier day cannot be anyone's boundary anymore
            }
            span[i] = stack.isEmpty() ? (i + 1) : (i - stack.peek());
            stack.push(i);
        }
        return span;
    }

    public static void main(String[] args) {
        int[] prices = {100, 80, 60, 70, 60, 75, 85};
        System.out.println(java.util.Arrays.toString(calculateSpan(prices)));
    }
}
// OUTPUT:
// [1, 1, 1, 2, 1, 4, 6]

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class StockSpanner {

    // Each stack entry pairs a price with its span, so popped spans can be reused
    private final Deque<int[]> stack = new ArrayDeque<>();   // {price, span}

    public int next(int price) {
        int span = 1;
        while (!stack.isEmpty() && stack.peek()[0] <= price) {
            span += stack.pop()[1];   // absorb the popped day's span into this one
        }
        stack.push(new int[]{price, span});
        return span;
    }

    public static void main(String[] args) {
        StockSpanner spanner = new StockSpanner();
        int[] prices = {100, 80, 60, 70, 60, 75, 85};
        for (int p : prices) {
            System.out.print(spanner.next(p) + " ");
        }
    }
}
// OUTPUT:
// 1 1 1 2 1 4 6

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class EvaluatePostfixDemo {

    static int evaluate(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();

        for (String token : tokens) {
            switch (token) {
                case "+": case "-": case "*": case "/": {
                    int b = stack.pop();
                    int a = stack.pop();
                    stack.push(apply(a, b, token));
                    break;
                }
                default:
                    stack.push(Integer.parseInt(token));
            }
        }
        return stack.pop();
    }

    static int apply(int a, int b, String op) {
        switch (op) {
            case "+": return a + b;
            case "-": return a - b;
            case "*": return a * b;
            case "/": return a / b;
            default: throw new IllegalArgumentException("Unknown operator: " + op);
        }
    }

    public static void main(String[] args) {
        // "3 4 + 2 *" means (3 + 4) * 2
        String[] tokens = {"3", "4", "+", "2", "*"};
        System.out.println(evaluate(tokens));
    }
}
// OUTPUT:
// 14

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class EvaluateInfixDemo {

    static int precedence(char op) {
        if (op == '+' || op == '-') return 1;
        if (op == '*' || op == '/') return 2;
        return 0;
    }

    static int applyOp(int a, int b, char op) {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return a * b;
            case '/': return a / b;
            default: throw new IllegalArgumentException();
        }
    }

    static int evaluate(String expr) {
        Deque<Integer> nums = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();
        int i = 0;

        while (i < expr.length()) {
            char c = expr.charAt(i);
            if (c == ' ') { i++; continue; }

            if (Character.isDigit(c)) {
                int num = 0;
                while (i < expr.length() && Character.isDigit(expr.charAt(i))) {
                    num = num * 10 + (expr.charAt(i) - '0');
                    i++;
                }
                nums.push(num);
                continue;
            } else if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (ops.peek() != '(') {
                    nums.push(applyOp(nums.pop(), nums.pop(), ops.pop()));
                }
                ops.pop();   // discard the '('
            } else {   // an operator
                while (!ops.isEmpty() && precedence(ops.peek()) >= precedence(c)) {
                    nums.push(applyOp(nums.pop(), nums.pop(), ops.pop()));
                }
                ops.push(c);
            }
            i++;
        }

        while (!ops.isEmpty()) {
            nums.push(applyOp(nums.pop(), nums.pop(), ops.pop()));
        }
        return nums.pop();
    }

    public static void main(String[] args) {
        System.out.println(evaluate("3 + 5 * ( 2 - 8 )"));
    }
}
// OUTPUT:
// -27

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class InfixToPostfixDemo {

    static int precedence(char op) {
        if (op == '+' || op == '-') return 1;
        if (op == '*' || op == '/') return 2;
        return 0;
    }

    // Shunting Yard: converts infix "a+b*c" style input into postfix "abc*+"
    static String infixToPostfix(String infix) {
        StringBuilder output = new StringBuilder();
        Deque<Character> ops = new ArrayDeque<>();

        for (char c : infix.toCharArray()) {
            if (Character.isLetterOrDigit(c)) {
                output.append(c);
            } else if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (ops.peek() != '(') {
                    output.append(ops.pop());
                }
                ops.pop();
            } else {   // operator
                while (!ops.isEmpty() && precedence(ops.peek()) >= precedence(c)) {
                    output.append(ops.pop());
                }
                ops.push(c);
            }
        }
        while (!ops.isEmpty()) {
            output.append(ops.pop());
        }
        return output.toString();
    }

    public static void main(String[] args) {
        System.out.println(infixToPostfix("a+b*c"));
        System.out.println(infixToPostfix("(a+b)*c"));
    }
}
// OUTPUT:
// abc*+
// ab+c*

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class InfixToPrefixDemo {

    static int precedence(char op) {
        if (op == '+' || op == '-') return 1;
        if (op == '*' || op == '/') return 2;
        return 0;
    }

    static String infixToPostfix(String infix) {
        StringBuilder output = new StringBuilder();
        Deque<Character> ops = new ArrayDeque<>();
        for (char c : infix.toCharArray()) {
            if (Character.isLetterOrDigit(c)) {
                output.append(c);
            } else if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (ops.peek() != '(') output.append(ops.pop());
                ops.pop();
            } else {
                // NOTE: for right-to-left prefix conversion, equal precedence should NOT
                // pop (keeps left-to-right operators grouped correctly once re-reversed)
                while (!ops.isEmpty() && precedence(ops.peek()) > precedence(c)) {
                    output.append(ops.pop());
                }
                ops.push(c);
            }
        }
        while (!ops.isEmpty()) output.append(ops.pop());
        return output.toString();
    }

    static String reverseAndSwapParens(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == '(') sb.append(')');
            else if (c == ')') sb.append('(');
            else sb.append(c);
        }
        return sb.toString();
    }

    static String infixToPrefix(String infix) {
        String reversed = reverseAndSwapParens(infix);
        String postfixOfReversed = infixToPostfix(reversed);
        return new StringBuilder(postfixOfReversed).reverse().toString();
    }

    public static void main(String[] args) {
        System.out.println(infixToPrefix("a+b*c"));
    }
}
// OUTPUT:
// +a*bc

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class MinStackDemo {

    static class MinStack {
        private final Deque<Integer> stack = new ArrayDeque<>();
        private final Deque<Integer> minStack = new ArrayDeque<>();   // tracks running minimum

        void push(int val) {
            stack.push(val);
            // push the SMALLER of val and the current min - minStack always mirrors stack's size
            minStack.push(minStack.isEmpty() ? val : Math.min(val, minStack.peek()));
        }

        void pop() {
            stack.pop();
            minStack.pop();   // both stacks shrink together, staying in sync
        }

        int top() {
            return stack.peek();
        }

        int getMin() {
            return minStack.peek();   // O(1) - always up to date
        }
    }

    public static void main(String[] args) {
        MinStack ms = new MinStack();
        ms.push(5);
        ms.push(3);
        ms.push(7);
        System.out.println("Min: " + ms.getMin());   // 3
        ms.pop();   // removes 7
        System.out.println("Min: " + ms.getMin());   // still 3
        ms.pop();   // removes 3
        System.out.println("Min: " + ms.getMin());   // back to 5
    }
}
// OUTPUT:
// Min: 3
// Min: 3
// Min: 5

package com.javaschoollab;

import java.util.ArrayDeque;
import java.util.Deque;

public class MinStackOneStackDemo {

    static class MinStack {
        private final Deque<Long> stack = new ArrayDeque<>();
        private long min = Long.MAX_VALUE;

        void push(int val) {
            if (stack.isEmpty()) {
                stack.push((long) val);
                min = val;
            } else if (val >= min) {
                stack.push((long) val);            // normal value, no encoding needed
            } else {
                // encode: push a value that lets us recover the OLD min on pop
                stack.push(2L * val - min);
                min = val;                          // new minimum
            }
        }

        void pop() {
            long top = stack.pop();
            if (top < min) {
                min = 2 * min - top;   // decode: restore the previous minimum
            }
        }

        int top() {
            long top = stack.peek();
            return (int) (top < min ? min : top);   // encoded values aren't the real top
        }

        int getMin() {
            return (int) min;
        }
    }

    public static void main(String[] args) {
        MinStack ms = new MinStack();
        ms.push(5);
        ms.push(3);
        ms.push(7);
        System.out.println("Min: " + ms.getMin() + ", Top: " + ms.top());
        ms.pop();
        System.out.println("Min: " + ms.getMin() + ", Top: " + ms.top());
    }
}
// OUTPUT:
// Min: 3, Top: 7
// Min: 3, Top: 3

