package com.javaschoollab;

public class NaiveArrayQueueDemo {

    static class SlowQueue {
        private final int[] data;
        private int size = 0;

        SlowQueue(int capacity) { data = new int[capacity]; }

        void enqueue(int val) {
            data[size++] = val;
        }

        // O(n) - every remaining element must shift down by one
        int dequeue() {
            int front = data[0];
            for (int i = 1; i < size; i++) {
                data[i - 1] = data[i];
            }
            size--;
            return front;
        }
    }

    public static void main(String[] args) {
        SlowQueue q = new SlowQueue(5);
        q.enqueue(1);
        q.enqueue(2);
        q.enqueue(3);

        System.out.println("Dequeued: " + q.dequeue());
        // Notice dequeue() had to shift elements 2 and 3 down - O(n) work
        // for what should be an O(1) operation. This is exactly what
        // ArrayDeque's circular buffer avoids.
    }
}
// OUTPUT:
// Dequeued: 1

package com.javaschoollab;

public class CircularQueueDemo {

    static class CircularQueue {
        private final int[] data;
        private int front = 0, size = 0;
        private final int capacity;

        CircularQueue(int capacity) {
            this.capacity = capacity;
            data = new int[capacity];
        }

        boolean enqueue(int val) {
            if (size == capacity) return false;   // full
            int rear = (front + size) % capacity;   // wraps around automatically
            data[rear] = val;
            size++;
            return true;
        }

        int dequeue() {
            if (size == 0) throw new RuntimeException("Queue is empty");
            int val = data[front];
            front = (front + 1) % capacity;   // wraps around too
            size--;
            return val;
        }
    }

    public static void main(String[] args) {
        CircularQueue q = new CircularQueue(3);
        q.enqueue(1);
        q.enqueue(2);
        q.enqueue(3);

        System.out.println(q.dequeue());   // frees up slot 0
        q.enqueue(4);                       // reuses slot 0 - wraps around

        System.out.println(q.dequeue());
        System.out.println(q.dequeue());
        System.out.println(q.dequeue());
    }
}
// OUTPUT:
// 1
// 2
// 3
// 4

package com.javaschoollab;

public class CircularQueueOneSlotWastedDemo {

    // Alternative design: no 'size' field, distinguishes full/empty by
    // always leaving ONE slot unused - a classic embedded-systems technique.
    static class CircularQueue {
        private final int[] data;
        private int front = 0, rear = 0;
        private final int capacity;   // real usable capacity is capacity - 1

        CircularQueue(int capacity) {
            this.capacity = capacity + 1;   // reserve one extra slot
            data = new int[this.capacity];
        }

        boolean isFull() {
            return (rear + 1) % capacity == front;
        }

        boolean isEmpty() {
            return front == rear;
        }

        boolean enqueue(int val) {
            if (isFull()) return false;
            data[rear] = val;
            rear = (rear + 1) % capacity;
            return true;
        }

        int dequeue() {
            if (isEmpty()) throw new RuntimeException("Queue is empty");
            int val = data[front];
            front = (front + 1) % capacity;
            return val;
        }
    }

    public static void main(String[] args) {
        CircularQueue q = new CircularQueue(3);   // usable capacity: 3
        q.enqueue(1); q.enqueue(2); q.enqueue(3);
        System.out.println("Full? " + q.isFull());
        System.out.println(q.dequeue());
        System.out.println("Full after dequeue? " + q.isFull());
    }
}
// OUTPUT:
// Full? true
// 1
// Full after dequeue? false

