public class CountingSortRangeDemo {
    public static void main(String[] args) {
        // Counting sort shines when k (the value range) is comparable to n
        int[] smallRange = {5, 3, 5, 1, 4, 2, 5, 3};   // values 1-5, n=8 -> great fit
