package com.javaschoollab;

public class LcaBinaryTreeDemo {

    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static TreeNode lca(TreeNode node, TreeNode p, TreeNode q) {
        if (node == null || node == p || node == q) {
            return node;   // found one of the targets, or hit the bottom
        }

        TreeNode leftResult = lca(node.left, p, q);
        TreeNode rightResult = lca(node.right, p, q);

        if (leftResult != null && rightResult != null) {
            return node;   // p and q found in DIFFERENT subtrees - this node IS the LCA
        }
        return (leftResult != null) ? leftResult : rightResult;   // bubble up whichever was found
    }

    public static void main(String[] args) {
        TreeNode root = new TreeNode(3);
        TreeNode five = new TreeNode(5);
        TreeNode one = new TreeNode(1);
        root.left = five;
        root.right = one;
        TreeNode six = new TreeNode(6);
        TreeNode two = new TreeNode(2);
        five.left = six;
        five.right = two;

        TreeNode result = lca(root, six, two);
        System.out.println("LCA: " + result.val);
    }
}
// OUTPUT:
// LCA: 5

package com.javaschoollab;

public class LcaBstDemo {

    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static TreeNode lcaBst(TreeNode node, int p, int q) {
        while (node != null) {
            if (p < node.val && q < node.val) {
                node = node.left;    // both targets are smaller - LCA must be in the left subtree
            } else if (p > node.val && q > node.val) {
                node = node.right;   // both targets are bigger - LCA must be in the right subtree
            } else {
                return node;         // split point (or node IS p or q) - this is the LCA
            }
        }
        return null;
    }

    public static void main(String[] args) {
        TreeNode root = new TreeNode(6);
        root.left = new TreeNode(2);
        root.right = new TreeNode(8);
        root.left.left = new TreeNode(0);
        root.left.right = new TreeNode(4);

        TreeNode result = lcaBst(root, 0, 4);
        System.out.println("LCA: " + result.val);
    }
}
// OUTPUT:
// LCA: 2

package com.javaschoollab;

public class PathSumDemo {

    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static boolean hasPathSum(TreeNode node, int target) {
        if (node == null) return false;

        // A leaf: check if the remaining target is exactly used up
        if (node.left == null && node.right == null) {
            return target == node.val;
        }

        int remaining = target - node.val;
        return hasPathSum(node.left, remaining) || hasPathSum(node.right, remaining);
    }

    public static void main(String[] args) {
        TreeNode root = new TreeNode(5);
        root.left = new TreeNode(4);
        root.right = new TreeNode(8);
        root.left.left = new TreeNode(11);
        root.left.left.left = new TreeNode(7);
        root.left.left.right = new TreeNode(2);

        System.out.println(hasPathSum(root, 22));   // 5+4+11+2 = 22
        System.out.println(hasPathSum(root, 100));
    }
}
// OUTPUT:
// true
// false

package com.javaschoollab;

import java.util.ArrayList;
import java.util.List;

public class AllPathSumsDemo {

    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static List<List<Integer>> findAllPaths(TreeNode root, int target) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(root, target, new ArrayList<>(), result);
        return result;
    }

    static void backtrack(TreeNode node, int remaining, List<Integer> path, List<List<Integer>> result) {
        if (node == null) return;

        path.add(node.val);   // choose: add this node to the current path

        if (node.left == null && node.right == null && remaining == node.val) {
            result.add(new ArrayList<>(path));   // COPY, since 'path' keeps mutating
        } else {
            backtrack(node.left, remaining - node.val, path, result);
            backtrack(node.right, remaining - node.val, path, result);
        }

        path.remove(path.size() - 1);   // un-choose: backtrack before returning to the parent
    }

    public static void main(String[] args) {
        TreeNode root = new TreeNode(5);
        root.left = new TreeNode(4);
        root.right = new TreeNode(8);
        root.left.left = new TreeNode(11);
        root.left.left.left = new TreeNode(7);
        root.left.left.right = new TreeNode(2);

        System.out.println(findAllPaths(root, 22));
    }
}
// OUTPUT:
// [[5, 4, 11, 2]]

package com.javaschoollab;

import java.util.*;

public class LeftViewDemo {

    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static List<Integer> leftView(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) return result;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                if (i == 0) result.add(node.val);   // FIRST node of this level
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
        }
        return result;
    }

