package com.javaschoollab;

import java.util.ArrayList;
import java.util.List;

public class MinHeapFromScratchDemo {

    static class MinHeap {
        private final List<Integer> heap = new ArrayList<>();

        void insert(int val) {
            heap.add(val);
            swim(heap.size() - 1);
        }

        int extractMin() {
            int min = heap.get(0);
            int last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                sink(0);
            }
            return min;
        }

        void swim(int i) {
            while (i > 0) {
                int parent = (i - 1) / 2;
                if (heap.get(i) >= heap.get(parent)) break;
                swap(i, parent);
                i = parent;
            }
        }

        void sink(int i) {
            int n = heap.size();
            while (true) {
                int left = 2 * i + 1, right = 2 * i + 2, smallest = i;
                if (left < n && heap.get(left) < heap.get(smallest)) smallest = left;
                if (right < n && heap.get(right) < heap.get(smallest)) smallest = right;
                if (smallest == i) break;
                swap(i, smallest);
                i = smallest;
            }
        }

        void swap(int i, int j) {
            int temp = heap.get(i);
            heap.set(i, heap.get(j));
            heap.set(j, temp);
        }
    }

    public static void main(String[] args) {
        MinHeap heap = new MinHeap();
        for (int v : new int[]{20, 5, 15, 1, 8}) heap.insert(v);

        for (int i = 0; i < 5; i++) {
            System.out.print(heap.extractMin() + " ");
        }
    }
}
// OUTPUT:
// 1 5 8 15 20

