        for (int num : arr) minHeap.offer(num);   // O(n) via bulk-insert internally

        int[] sorted = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            sorted[i] = minHeap.poll();   // always extracts the current smallest
        }
        return sorted;
    }

