package com.javaschoollab;

import java.util.Random;

public class QuickselectDemo {

    static final Random RANDOM = new Random();

    static int findKthLargest(int[] nums, int k) {
        int targetIndex = nums.length - k;   // Kth largest = (n-k)th smallest in sorted order
        return quickSelect(nums, 0, nums.length - 1, targetIndex);
    }

    static int quickSelect(int[] arr, int low, int high, int targetIndex) {
        int pivotIndex = partition(arr, low, high);

        if (pivotIndex == targetIndex) {
            return arr[pivotIndex];
        } else if (pivotIndex < targetIndex) {
            return quickSelect(arr, pivotIndex + 1, high, targetIndex);   // recurse RIGHT only
        } else {
            return quickSelect(arr, low, pivotIndex - 1, targetIndex);    // recurse LEFT only
        }
    }

    static int partition(int[] arr, int low, int high) {
        int randomIndex = low + RANDOM.nextInt(high - low + 1);
        swap(arr, randomIndex, high);

        int pivot = arr[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (arr[j] < pivot) {
                i++;
                swap(arr, i, j);
            }
        }
        swap(arr, i + 1, high);
        return i + 1;
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }

    public static void main(String[] args) {
        int[] nums = {3, 2, 1, 5, 6, 4};
        System.out.println(findKthLargest(nums, 2));
    }
}
// OUTPUT:
// 5

package com.javaschoollab;

import java.util.*;

public class TopKFrequentDemo {

    // Top K most FREQUENT elements - combines a frequency map with a heap
    static int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int n : nums) freq.merge(n, 1, Integer::sum);

        // Min-heap of size k, ordered by FREQUENCY (not value)
        PriorityQueue<Map.Entry<Integer, Integer>> minHeap =
            new PriorityQueue<>(Comparator.comparingInt(Map.Entry::getValue));

        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            minHeap.offer(entry);
            if (minHeap.size() > k) {
                minHeap.poll();   // evict the least frequent
            }
        }

        int[] result = new int[k];
        for (int i = k - 1; i >= 0; i--) {
            result[i] = minHeap.poll().getKey();
        }
        return result;
    }

    public static void main(String[] args) {
        int[] nums = {1, 1, 1, 2, 2, 3};
        System.out.println(Arrays.toString(topKFrequent(nums, 2)));
    }
}
// OUTPUT:
// [1, 2]

package com.javaschoollab;

import java.util.PriorityQueue;

public class KClosestPointsDemo {

    static int[][] kClosest(int[][] points, int k) {
        // Max-heap of size k, ordered by DISTANCE - largest distance evicted first
        PriorityQueue<int[]> maxHeap = new PriorityQueue<>(
            (a, b) -> (b[0] * b[0] + b[1] * b[1]) - (a[0] * a[0] + a[1] * a[1]));

        for (int[] point : points) {
            maxHeap.offer(point);
            if (maxHeap.size() > k) {
                maxHeap.poll();   // evict the FARTHEST point
            }
        }
        return maxHeap.toArray(new int[0][]);
    }

    public static void main(String[] args) {
        int[][] points = {{1, 3}, {-2, 2}, {5, 8}, {0, 1}};
        int[][] closest = kClosest(points, 2);
        for (int[] p : closest) {
            System.out.println(java.util.Arrays.toString(p));
        }
    }
}
