package com.javaschoollab;

import java.util.ArrayList;
import java.util.List;

public class SubsetsDemo {

    static List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(nums, 0, new ArrayList<>(), result);
        return result;
    }

    static void backtrack(int[] nums, int index, List<Integer> current, List<List<Integer>> result) {
        if (index == nums.length) {
            result.add(new ArrayList<>(current));   // record this subset (a COPY)
            return;
        }

        // Choice 1: EXCLUDE nums[index]
        backtrack(nums, index + 1, current, result);

        // Choice 2: INCLUDE nums[index]
        current.add(nums[index]);
        backtrack(nums, index + 1, current, result);
        current.remove(current.size() - 1);   // backtrack: undo the inclusion
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        System.out.println(subsets(nums));
    }
}
// OUTPUT:
// [[], [3], [2], [2, 3], [1], [1, 3], [1, 2], [1, 2, 3]]

package com.javaschoollab;

import java.util.*;

public class SubsetsWithDuplicatesDemo {

    static List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);   // group duplicates together - required for the skip logic to work
        List<List<Integer>> result = new ArrayList<>();
        backtrack(nums, 0, new ArrayList<>(), result);
        return result;
    }

    static void backtrack(int[] nums, int start, List<Integer> current, List<List<Integer>> result) {
        result.add(new ArrayList<>(current));   // every prefix IS a valid subset here

        for (int i = start; i < nums.length; i++) {
            // Skip duplicates AT THE SAME RECURSION LEVEL (not globally)
            if (i > start && nums[i] == nums[i - 1]) continue;

            current.add(nums[i]);
            backtrack(nums, i + 1, current, result);
            current.remove(current.size() - 1);
        }
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 2};
        System.out.println(subsetsWithDup(nums));
    }
}
// OUTPUT:
// [[], [1], [1, 2], [1, 2, 2], [2], [2, 2]]

package com.javaschoollab;

import java.util.ArrayList;
import java.util.List;

public class SubsequencesWithSumDemo {

    // Finds all subsequences that sum to EXACTLY target
    static List<List<Integer>> subsequencesWithSum(int[] arr, int target) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(arr, 0, target, new ArrayList<>(), result);
        return result;
    }

    static void backtrack(int[] arr, int index, int remaining, List<Integer> current, List<List<Integer>> result) {
        if (index == arr.length) {
            if (remaining == 0) {
                result.add(new ArrayList<>(current));
            }
            return;
        }

        // Include arr[index]
        current.add(arr[index]);
        backtrack(arr, index + 1, remaining - arr[index], current, result);
        current.remove(current.size() - 1);   // backtrack

        // Exclude arr[index]
        backtrack(arr, index + 1, remaining, current, result);
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4};
        System.out.println(subsequencesWithSum(arr, 5));
    }
}
// OUTPUT:
// [[1, 4], [2, 3]]

