package com.javaschoollab;

public class NQueensDemo {

    static int count = 0;

    static boolean isSafe(int[] queens, int row, int col) {
        for (int prevRow = 0; prevRow < row; prevRow++) {
            int prevCol = queens[prevRow];
            if (prevCol == col) return false;                            // same column
            if (Math.abs(prevCol - col) == Math.abs(prevRow - row)) return false;   // same diagonal
        }
        return true;
    }

    static void solve(int[] queens, int row, int n) {
        if (row == n) {
            count++;
            return;
        }
        for (int col = 0; col < n; col++) {
            if (isSafe(queens, row, col)) {
                queens[row] = col;
                solve(queens, row + 1, n);   // move to the NEXT row
                // no explicit undo needed - queens[row] gets overwritten next iteration
            }
        }
    }

    public static void main(String[] args) {
        int n = 8;
        count = 0;
        solve(new int[n], 0, n);
        System.out.println("Total solutions for " + n + "-Queens: " + count);
    }
}
// OUTPUT:
// Total solutions for 8-Queens: 92

package com.javaschoollab;

public class NQueensBitmaskDemo {

    static int count = 0;

    // cols, diag1 ("\" direction), diag2 ("/" direction) track occupied lines as bits
    static void solve(int row, int n, int cols, int diag1, int diag2) {
        if (row == n) {
            count++;
            return;
        }

        // Bits that are safe to place a queen at, in this row
        int availablePositions = ((1 << n) - 1) & ~(cols | diag1 | diag2);

        while (availablePositions != 0) {
            int position = availablePositions & (-availablePositions);   // isolate the lowest set bit
            availablePositions -= position;                              // remove it from options

            solve(row + 1, n,
                  cols | position,
                  (diag1 | position) << 1,
                  (diag2 | position) >> 1);
        }
    }

    public static void main(String[] args) {
        int n = 8;
        count = 0;
        solve(0, n, 0, 0, 0);
        System.out.println("Total solutions for " + n + "-Queens: " + count);
    }
}
// OUTPUT:
// Total solutions for 8-Queens: 92

package com.javaschoollab;

public class SudokuSolverDemo {

    static boolean isValid(char[][] board, int row, int col, char digit) {
        for (int i = 0; i < 9; i++) {
            if (board[row][i] == digit) return false;                                    // row
            if (board[i][col] == digit) return false;                                    // column
            int boxRow = 3 * (row / 3) + i / 3, boxCol = 3 * (col / 3) + i % 3;
            if (board[boxRow][boxCol] == digit) return false;                             // 3x3 box
        }
        return true;
    }

    static boolean solve(char[][] board) {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] != '.') continue;   // already filled

                for (char digit = '1'; digit <= '9'; digit++) {
                    if (isValid(board, row, col, digit)) {
                        board[row][col] = digit;

                        if (solve(board)) return true;   // continue with the rest of the board

                        board[row][col] = '.';   // backtrack - this digit didn't lead to a solution
                    }
                }
                return false;   // no digit 1-9 works here - dead end, backtrack further up
            }
        }
        return true;   // no empty cells left - solved!
    }

    public static void main(String[] args) {
        char[][] board = {
            {'5','3','.','.','7','.','.','.','.'},
            {'6','.','.','1','9','5','.','.','.'},
            {'.','9','8','.','.','.','.','6','.'},
            {'8','.','.','.','6','.','.','.','3'},
            {'4','.','.','8','.','3','.','.','1'},
            {'7','.','.','.','2','.','.','.','6'},
            {'.','6','.','.','.','.','2','8','.'},
            {'.','.','.','4','1','9','.','.','5'},
            {'.','.','.','.','8','.','.','7','9'}
        };
        solve(board);
        System.out.println(board[0][2] + " " + board[0][3]);   // two of the previously '.' cells
    }
}
// OUTPUT:
// 4 6

