// 3. That false bubbles back up through every intermediate recursive call.
// 4. Each intermediate cell, upon seeing false, resets ITS digit and tries the next one.
// 5. Eventually cell A itself may need to try digit 6 instead of 5, and so on.
//
// Without resetting board[row][col] = '.' on failure, stale digits would
// incorrectly block otherwise-valid future placements.

package com.javaschoollab;

import java.util.ArrayList;
import java.util.List;

public class RatInMazeDemo {

    static void findPath(int[][] maze, int row, int col, boolean[][] visited,
                          StringBuilder path, List<String> result) {
        int n = maze.length;

        if (row == n - 1 && col == n - 1) {
            result.add(path.toString());
            return;
        }

        int[] dr = {1, 0, 0, -1};   // Down, Left, Right, Up (conventional order: D L R U)
        int[] dc = {0, -1, 1, 0};
        char[] moveChar = {'D', 'L', 'R', 'U'};

        for (int d = 0; d < 4; d++) {
            int nr = row + dr[d], nc = col + dc[d];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n
                    && maze[nr][nc] == 1 && !visited[nr][nc]) {

                visited[nr][nc] = true;
                path.append(moveChar[d]);

                findPath(maze, nr, nc, visited, path, result);

                path.deleteCharAt(path.length() - 1);   // backtrack: undo the move
                visited[nr][nc] = false;                  // backtrack: unmark visited
            }
        }
    }

    public static void main(String[] args) {
        int[][] maze = {
            {1, 0, 0, 0},
            {1, 1, 0, 1},
            {1, 1, 0, 0},
            {0, 1, 1, 1}
        };

        boolean[][] visited = new boolean[4][4];
        visited[0][0] = true;
        List<String> result = new ArrayList<>();
        findPath(maze, 0, 0, visited, new StringBuilder(), result);

        System.out.println(result);
    }
}
// OUTPUT:
// [DDRDRR]

