package com.javaschoollab;

import java.util.ArrayList;
import java.util.List;

public class GenerateParenthesesDemo {

    static List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        backtrack(new StringBuilder(), 0, 0, n, result);
        return result;
    }

    static void backtrack(StringBuilder current, int open, int close, int n, List<String> result) {
        if (current.length() == 2 * n) {
            result.add(current.toString());
            return;
        }

        if (open < n) {
            current.append('(');
            backtrack(current, open + 1, close, n, result);
            current.deleteCharAt(current.length() - 1);   // backtrack
        }

        if (close < open) {   // only close if there's an unmatched open to close
            current.append(')');
            backtrack(current, open, close + 1, n, result);
            current.deleteCharAt(current.length() - 1);   // backtrack
        }
    }

    public static void main(String[] args) {
        System.out.println(generateParenthesis(3));
    }
}
// OUTPUT:
// [((())), (()()), (())(), ()(()), ()()()]

package com.javaschoollab;

public class WhyCloseCheckMattersDemo {
    public static void main(String[] args) {
        // Without the "close < open" guard, invalid sequences like ")(" would be generated.
        // With it: at EVERY point during generation, close <= open is maintained -
        // which is the textbook definition of a "balanced prefix".

        System.out.println("open=2, close=1: close < open is TRUE -> allowed to add ')'");
        System.out.println("open=1, close=1: close < open is FALSE -> NOT allowed to add ')' yet");
        System.out.println("(adding ')' here would make close > open, producing an invalid prefix like '())')");
    }
}
// OUTPUT:
// open=2, close=1: close < open is TRUE -> allowed to add ')'
// open=1, close=1: close < open is FALSE -> NOT allowed to add ')' yet
// (adding ')' here would make close > open, producing an invalid prefix like '())')

package com.javaschoollab;

public class PruningVsNoPruningDemo {

    static int callsWithoutPruning = 0;
    static int callsWithPruning = 0;

    // Finds a subset of arr summing to EXACTLY target - WITHOUT pruning
    static boolean withoutPruning(int[] arr, int index, int remaining) {
        callsWithoutPruning++;
        if (remaining == 0) return true;
        if (index == arr.length) return false;

        return withoutPruning(arr, index + 1, remaining - arr[index])
            || withoutPruning(arr, index + 1, remaining);
    }

    // SAME problem, but prunes the moment remaining goes negative
    static boolean withPruning(int[] arr, int index, int remaining) {
        callsWithPruning++;
        if (remaining == 0) return true;
        if (index == arr.length || remaining < 0) return false;   // PRUNE: no point going further

        return withPruning(arr, index + 1, remaining - arr[index])
            || withPruning(arr, index + 1, remaining);
    }

    public static void main(String[] args) {
        int[] arr = {10, 20, 30, 40, 50};

        callsWithoutPruning = 0;
        withoutPruning(arr, 0, 5);   // impossible target - explores EVERYTHING anyway
        System.out.println("Calls without pruning: " + callsWithoutPruning);

        callsWithPruning = 0;
        withPruning(arr, 0, 5);      // prunes as soon as remaining < 0
        System.out.println("Calls with pruning   : " + callsWithPruning);
    }
}
// OUTPUT:
// Calls without pruning: 63
// Calls with pruning   : 11

package com.javaschoollab;

public class PruningStrategiesDemo {

    // Constraint pruning: check safety BEFORE recursing (N-Queens style), not after
    static boolean isSafe(int[] placed, int row, int col) {
        for (int r = 0; r < row; r++) {
            if (placed[r] == col || Math.abs(placed[r] - col) == row - r) return false;
        }
        return true;
    }

    static int solutions = 0;

    static void solveNQueens(int[] placed, int row, int n) {
        if (row == n) { solutions++; return; }

        for (int col = 0; col < n; col++) {
            // PRUNE HERE: check validity before committing to recursion,
            // not after building the full board and checking at the end
            if (isSafe(placed, row, col)) {
                placed[row] = col;
                solveNQueens(placed, row + 1, n);
            }
        }
    }

    public static void main(String[] args) {
        solutions = 0;
        solveNQueens(new int[6], 0, 6);
        System.out.println("6-Queens solutions: " + solutions);
        System.out.println("Constraint pruning avoided exploring millions of invalid full boards.");
    }
}
// OUTPUT:
// 6-Queens solutions: 4
// Constraint pruning avoided exploring millions of invalid full boards.

package com.javaschoollab;

import java.util.*;

public class GraphColoringDemo {

    // Assigns one of 'numColors' colors to each vertex so no edge connects
    // two same-colored vertices - a classic CSP
    static boolean solve(Map<Integer, List<Integer>> graph, int[] colors, int vertex, int numVertices, int numColors) {
        if (vertex == numVertices) return true;   // all vertices colored successfully

        for (int color = 1; color <= numColors; color++) {
            if (isValidColor(graph, colors, vertex, color)) {
                colors[vertex] = color;

                if (solve(graph, colors, vertex + 1, numVertices, numColors)) {
                    return true;
                }
                colors[vertex] = 0;   // backtrack
            }
        }
        return false;
    }

    static boolean isValidColor(Map<Integer, List<Integer>> graph, int[] colors, int vertex, int color) {
        for (int neighbor : graph.getOrDefault(vertex, List.of())) {
            if (colors[neighbor] == color) return false;   // constraint violated
        }
        return true;
    }

    public static void main(String[] args) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        graph.put(0, List.of(1, 2));
        graph.put(1, List.of(0, 2));
        graph.put(2, List.of(0, 1, 3));
        graph.put(3, List.of(2));

        int[] colors = new int[4];
        boolean success = solve(graph, colors, 0, 4, 3);
        System.out.println("Solvable with 3 colors: " + success);
        System.out.println("Colors: " + java.util.Arrays.toString(colors));
    }
}
// OUTPUT:
// Solvable with 3 colors: true
// Colors: [1, 2, 3, 1]

