package com.javaschoollab;

public class MatrixChainMultiplicationDemo {

    // dims[i-1] x dims[i] is the size of matrix i (1-indexed matrices)
    static int matrixChainOrder(int[] dims) {
        int n = dims.length - 1;   // number of matrices
        int[][] dp = new int[n + 1][n + 1];

        // Fill by increasing CHAIN LENGTH - shorter chains must be solved first
        for (int len = 2; len <= n; len++) {
            for (int i = 1; i <= n - len + 1; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;

                for (int k = i; k < j; k++) {
                    int cost = dp[i][k] + dp[k + 1][j] + dims[i - 1] * dims[k] * dims[j];
                    dp[i][j] = Math.min(dp[i][j], cost);
                }
            }
        }
        return dp[1][n];
    }

    public static void main(String[] args) {
        // Matrices: 10x30, 30x5, 5x60 -> dims = {10, 30, 5, 60}
        int[] dims = {10, 30, 5, 60};
        System.out.println(matrixChainOrder(dims));
    }
}
// OUTPUT:
// 4500

package com.javaschoollab;

public class MatrixChainReconstructionDemo {

    static int[][] split;

    static int matrixChainOrder(int[] dims) {
        int n = dims.length - 1;
        int[][] dp = new int[n + 1][n + 1];
        split = new int[n + 1][n + 1];

        for (int len = 2; len <= n; len++) {
            for (int i = 1; i <= n - len + 1; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    int cost = dp[i][k] + dp[k + 1][j] + dims[i - 1] * dims[k] * dims[j];
                    if (cost < dp[i][j]) {
                        dp[i][j] = cost;
                        split[i][j] = k;   // remember the BEST split point
                    }
                }
            }
        }
        return dp[1][n];
    }

    static String buildOrder(int i, int j) {
        if (i == j) return "M" + i;
        int k = split[i][j];
        return "(" + buildOrder(i, k) + " x " + buildOrder(k + 1, j) + ")";
    }

    public static void main(String[] args) {
        int[] dims = {10, 30, 5, 60};
        int minCost = matrixChainOrder(dims);
        System.out.println("Min cost: " + minCost);
        System.out.println("Optimal order: " + buildOrder(1, dims.length - 1));
    }
}
// OUTPUT:
// Min cost: 4500
// Optimal order: (M1 x (M2 x M3))

package com.javaschoollab;

public class BurstBalloonsDemo {

    static int maxCoins(int[] balloons) {
        int n = balloons.length;
        int[] nums = new int[n + 2];
        nums[0] = 1;
        nums[n + 1] = 1;   // virtual boundary balloons of value 1
        for (int i = 0; i < n; i++) nums[i + 1] = balloons[i];

        int[][] dp = new int[n + 2][n + 2];

        for (int len = 1; len <= n; len++) {
            for (int left = 1; left <= n - len + 1; left++) {
                int right = left + len - 1;

                for (int k = left; k <= right; k++) {
                    // k is the LAST balloon burst in [left, right] -
                    // its neighbors at that moment are nums[left-1] and nums[right+1]
                    int coins = nums[left - 1] * nums[k] * nums[right + 1]
                              + dp[left][k - 1] + dp[k + 1][right];
                    dp[left][right] = Math.max(dp[left][right], coins);
                }
            }
        }
        return dp[1][n];
    }

    public static void main(String[] args) {
        int[] balloons = {3, 1, 5, 8};
        System.out.println(maxCoins(balloons));
    }
}
// OUTPUT:
// 167

